EXTRA = ROOT / 'components/portal/admin-events-tidings-context.tsx'

if not (ROOT / 'package.json').exists():
    raise SystemExit('ERROR: Run from the sepulchria-portal repository root.')

for path in (KEEPER, SIDEBAR):
    if not path.exists():
        raise SystemExit(f'ERROR: Missing {path.relative_to(ROOT)}')

